"""The ordinal of every element, generated by the Python locator and checked by the desktop.

``apps/desktop/src/lib/design/__fixtures__/html-element-index.json`` holds, for each source, the
``[ordinal, tag]`` list the parser produces. The desktop's ``annotateForEditing`` and selection
script number the same sources, and ``htmlElements.test.ts`` reads this file to hold them to it.
Regenerate after an intended change to the locator with:

    HTML_INDEX_REGEN=1 python -m pytest tests/test_html_element_index_fixture.py
"""

from __future__ import annotations

import json
import os
from pathlib import Path

from chimera.design.html_source import list_start_tags

FIXTURE = (
    Path(__file__).resolve().parents[1]
    / "apps" / "desktop" / "src" / "lib" / "design" / "__fixtures__" / "html-element-index.json"
)

CORPUS = [
    "<main><p>a</p></main>",
    "<!doctype html><html><head><title>t</title><style>p{color:red}</style></head><body><p>x</p></body></html>",
    "<style>p{color:red}</style><main><p>x</p></main>",
    "<table><tr><td>1</td></tr></table>",
    "<p>a<p>b",
    '<svg viewBox="0 0 1 1"><path d="M0 0"/><g><text>x</text></g></svg>',
    "<div title='a > b' data-x=\"c > d\"><span>x</span></div>",
    "<!-- <div> --><section><b>x</b></section>",
    "<textarea><b></textarea><i>y</i>",
    "<title>a<b>c</title><main>z</main>",
    "<br/><img src=\"asset:x\"><hr>",
    "<main>a <p>b</p>\x0c<p>c\r\n<b>d</b></p></main>",
]


def _expected() -> dict[str, object]:
    return {
        "note": "Generated by tests/test_html_element_index_fixture.py. Do not edit by hand.",
        "cases": [
            {"source": source, "tags": [[index, tag] for index, (tag, _) in enumerate(list_start_tags(source))]}
            for source in CORPUS
        ],
    }


def test_the_desktop_fixture_is_the_python_locators_output() -> None:
    wanted = json.dumps(_expected(), indent=2, ensure_ascii=True) + "\n"
    if os.environ.get("HTML_INDEX_REGEN") == "1":
        FIXTURE.parent.mkdir(parents=True, exist_ok=True)
        FIXTURE.write_text(wanted, encoding="utf-8", newline="\n")
    current = FIXTURE.read_text(encoding="utf-8") if FIXTURE.exists() else None
    assert current == wanted, (
        f"{FIXTURE} is out of date with chimera/design/html_source.py. "
        "Regenerate it with: HTML_INDEX_REGEN=1 python -m pytest tests/test_html_element_index_fixture.py"
    )
